def maximum_subarray_sum(nums, k):
    n = len(nums)
    best = 0
    for start in range(n - k + 1):
        window = nums[start:start + k]
        if len(set(window)) == k:                                       # every element in this window is distinct
            best = max(best, sum(window))
    return best


