def maximum_subarray_sum(nums, k):
    freq = {}
    window_sum = 0
    best = 0
    for i, num in enumerate(nums):
        window_sum += num
        freq[num] = freq.get(num, 0) + 1
        if i >= k:
            leaving = nums[i - k]
            window_sum -= leaving
            freq[leaving] -= 1
            if freq[leaving] == 0:
                del freq[leaving]                                          # stop tracking a value once it's no longer in the window
        if i >= k - 1 and len(freq) == k:                                   # window is full size AND every value in it is distinct
            best = max(best, window_sum)
    return best


