import java.util.*;

public class Main {
    long maximumSubarraySum(int[] nums, int k) {
        Map<Integer, Integer> freq = new HashMap<>();
        long windowSum = 0;
        long best = 0;
        for (int i = 0; i < nums.length; i++) {
            windowSum += nums[i];
            freq.merge(nums[i], 1, Integer::sum);
            if (i >= k) {
                int leaving = nums[i - k];
                windowSum -= leaving;
                freq.merge(leaving, -1, Integer::sum);
                if (freq.get(leaving) == 0) freq.remove(leaving);                  // stop tracking a value once it's no longer in the window
            }
            if (i >= k - 1 && freq.size() == k) {                                  // window is full size AND every value in it is distinct
                best = Math.max(best, windowSum);
            }
        }
        return best;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.maximumSubarraySum(new int[]{1, 5, 4, 2, 9, 9, 9}, 3));
    }
}

