#include <bits/stdc++.h>
using namespace std;

long long maximumSubarraySum(vector<int>& nums, int k) {
    unordered_map<int,int> freq;
    long long windowSum = 0;
    long long best = 0;
    for (int i = 0; i < (int)nums.size(); i++) {
        windowSum += nums[i];
        freq[nums[i]]++;
        if (i >= k) {
            int leaving = nums[i - k];
            windowSum -= leaving;
            freq[leaving]--;
            if (freq[leaving] == 0) freq.erase(leaving);                        // stop tracking a value once it's no longer in the window
        }
        if (i >= k - 1 && (int)freq.size() == k) {                              // window is full size AND every value in it is distinct
            best = max(best, windowSum);
        }
    }
    return best;
}

